{"path": "forth.py", "content": "class StackUnderflowError(Exception):
    """Exception raised when the stack holds too few items for an operation.

    message: explanation of the error.
    """

    def __init__(self, message):
        super().__init__(message)
        self.message = message


def _is_number(token):
    body = token[1:] if token[:1] in "+-" and len(token) > 1 else token
    return body.isascii() and body.isdigit()


def _pop(stack, count):
    if len(stack) < count:
        raise StackUnderflowError("Insufficient number of items in stack")
    values = stack[-count:]
    del stack[-count:]
    return values


def _divide(a, b):
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    quotient = abs(a) // abs(b)
    return quotient if (a < 0) == (b < 0) else -quotient


_BINARY = {
    "+": lambda a, b: a + b,
    "-": lambda a, b: a - b,
    "*": lambda a, b: a * b,
    "/": _divide,
}


def _execute(token, stack):
    if _is_number(token):
        stack.append(int(token))
    elif token in _BINARY:
        a, b = _pop(stack, 2)
        stack.append(_BINARY[token](a, b))
    elif token == "dup":
        (a,) = _pop(stack, 1)
        stack.extend([a, a])
    elif token == "drop":
        _pop(stack, 1)
    elif token == "swap":
        a, b = _pop(stack, 2)
        stack.extend([b, a])
    elif token == "over":
        a, b = _pop(stack, 2)
        stack.extend([a, b, a])
    else:
        raise ValueError("undefined operation")


def evaluate(input_data):
    stack = []
    definitions = {}

    def expand(token):
        return definitions.get(token, [token])

    for line in input_data:
        tokens = line.lower().split()
        index = 0
        while index < len(tokens):
            token = tokens[index]
            if token == ":":
                try:
                    end = tokens.index(";", index)
                except ValueError:
                    raise ValueError("undefined operation") from None
                if end - index < 2:
                    raise ValueError("undefined operation")
                name = tokens[index + 1]
                if _is_number(name):
                    raise ValueError("illegal operation")
                body = []
                for word in tokens[index + 2:end]:
                    body.extend(expand(word))
                definitions[name] = body
                index = end + 1
                continue
            for word in expand(token):
                _execute(word, stack)
            index += 1
    return stack
